 CREATE   PROCEDURE studio.spChartControl     @Payload nvarchar(max) AS BEGIN     SET NOCOUNT ON;     SET XACT_ABORT ON;      IF @Payload IS NULL OR ISJSON(@Payload) <> 1     BEGIN         SELECT CAST(0 AS bit) AS success, 'CHART_INPUT_INVALID' AS code;         RETURN;     END;      DECLARE @User uniqueidentifier =         TRY_CONVERT(uniqueidentifier, JSON_VALUE(@Payload, '$.UserID'));      IF @User IS NULL        OR NOT EXISTS           (               SELECT 1               FROM dbo.core_user               WHERE user_id = @User                 AND is_active = 1                 AND is_locked = 0           )     BEGIN         SELECT CAST(0 AS bit) AS success, 'CHART_USER_UNAVAILABLE' AS code;         RETURN;     END;      DECLARE @Action varchar(10) =         UPPER(ISNULL(JSON_VALUE(@Payload, '$.Action'), ''));      IF @Action = 'LIST'     BEGIN         SELECT CAST(1 AS bit) AS success,                'CHART_LIST' AS code,                (                    SELECT LOWER(CONVERT(varchar(36), chart_id)) AS chart_id,                           chart_name AS name,                           version,                           JSON_QUERY(config_json) AS config,                           created_at,                           updated_at                    FROM studio.chart                    WHERE owner_user_id = @User                    ORDER BY updated_at DESC, chart_id                    FOR JSON PATH                ) AS items_json;         RETURN;     END;      IF @Action = 'GET'     BEGIN         DECLARE @GetID uniqueidentifier =             TRY_CONVERT(uniqueidentifier, JSON_VALUE(@Payload, '$.ChartID'));          IF @GetID IS NULL         BEGIN             SELECT CAST(0 AS bit) AS success, 'CHART_ID_INVALID' AS code;             RETURN;         END;          IF NOT EXISTS         (             SELECT 1             FROM studio.chart             WHERE chart_id = @GetID               AND owner_user_id = @User         )         BEGIN             SELECT CAST(0 AS bit) AS success, 'CHART_NOT_FOUND' AS code;             RETURN;         END;          SELECT CAST(1 AS bit) AS success,                'CHART_GET' AS code,                LOWER(CONVERT(varchar(36), chart_id)) AS chart_id,                chart_name,                version,                created_at,                updated_at,                config_json         FROM studio.chart         WHERE chart_id = @GetID           AND owner_user_id = @User;         RETURN;     END;      IF @Action = 'SAVE'     BEGIN         DECLARE @Name nvarchar(150) =             NULLIF(LTRIM(RTRIM(JSON_VALUE(@Payload, '$.ChartName'))), '');          /* ConfigJSON is a JSON string (json.dumps in Python). OPENJSON keeps            the full value instead of JSON_VALUE's 4000-character limit. */         DECLARE @Config nvarchar(max);         SELECT @Config = CAST([value] AS nvarchar(max))         FROM OPENJSON(@Payload)         WHERE [key] = N'ConfigJSON';          DECLARE @Expected int =             ISNULL(TRY_CONVERT(int, JSON_VALUE(@Payload, '$.ExpectedVersion')), 0);          DECLARE @SaveID uniqueidentifier =             TRY_CONVERT(uniqueidentifier, JSON_VALUE(@Payload, '$.ChartID'));          IF @Name IS NULL            OR LEN(@Name) > 150            OR @Config IS NULL            OR ISJSON(@Config) <> 1            OR DATALENGTH(@Config) > 262144            OR @Expected < 0            OR (JSON_VALUE(@Payload, '$.ChartID') IS NOT NULL AND @SaveID IS NULL)         BEGIN             SELECT CAST(0 AS bit) AS success, 'CHART_INPUT_INVALID' AS code;             RETURN;         END;          IF @SaveID IS NULL         BEGIN             DECLARE @NewID uniqueidentifier = NEWID();              BEGIN TRY
                BEGIN TRANSACTION;
                INSERT INTO studio.chart                 (chart_id, chart_name, config_json, version, owner_user_id)             VALUES                 (@NewID, @Name, @Config, 1, @User);
    /* PHASE2D3_ATOMIC_OWNERSHIP */
    INSERT INTO studio.object_ownership(object_type,object_id,owner_user_id)
    VALUES ('CHART',@NewID,@User);
    INSERT INTO studio.object_access_audit(actor_user_id,object_type,object_id,action_type,new_owner_user_id)
    VALUES (@User,'CHART',@NewID,'REGISTER',@User);
                COMMIT TRANSACTION;
            END TRY
            BEGIN CATCH
                IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
                THROW;
            END CATCH;
              SELECT CAST(1 AS bit) AS success,                    'CHART_SAVED' AS code,                    LOWER(CONVERT(varchar(36), @NewID)) AS chart_id,                    1 AS version;             RETURN;         END;          BEGIN TRY             BEGIN TRANSACTION;              UPDATE studio.chart WITH (UPDLOCK, ROWLOCK)             SET chart_name = @Name,                 config_json = @Config,                 version = version + 1,                 updated_at = SYSUTCDATETIME()             WHERE chart_id = @SaveID               AND owner_user_id = @User               AND version = @Expected;              IF @@ROWCOUNT = 0             BEGIN                 ROLLBACK TRANSACTION;                  IF EXISTS                 (                     SELECT 1                     FROM studio.chart                     WHERE chart_id = @SaveID                       AND owner_user_id = @User                 )                     SELECT CAST(0 AS bit) AS success,                            'CHART_VERSION_CONFLICT' AS code;                 ELSE                     SELECT CAST(0 AS bit) AS success,                            'CHART_NOT_FOUND' AS code;                 RETURN;              END;              COMMIT TRANSACTION;              SELECT CAST(1 AS bit) AS success,                    'CHART_UPDATED' AS code,                    LOWER(CONVERT(varchar(36), chart_id)) AS chart_id,                    version             FROM studio.chart             WHERE chart_id = @SaveID;             RETURN;         END TRY         BEGIN CATCH             IF @@TRANCOUNT > 0                 ROLLBACK TRANSACTION;              SELECT CAST(0 AS bit) AS success, 'CHART_SAVE_FAILED' AS code;             RETURN;         END CATCH;     END;      IF @Action = 'DELETE'     BEGIN         DECLARE @DeleteID uniqueidentifier =             TRY_CONVERT(uniqueidentifier, JSON_VALUE(@Payload, '$.ChartID'));          IF @DeleteID IS NULL         BEGIN             SELECT CAST(0 AS bit) AS success, 'CHART_ID_INVALID' AS code;             RETURN;         END;          DELETE FROM studio.chart         WHERE chart_id = @DeleteID           AND owner_user_id = @User;          IF @@ROWCOUNT = 0         BEGIN             SELECT CAST(0 AS bit) AS success, 'CHART_NOT_FOUND' AS code;             RETURN;         END;          SELECT CAST(1 AS bit) AS success, 'CHART_DELETED' AS code;         RETURN;     END;      SELECT CAST(0 AS bit) AS success, 'CHART_ACTION_INVALID' AS code; END; 